package com.bank.multistage;

import java.util.List;

// A base image with its size (MB) and the tools it contains.
public final class BaseImage {
    private final String name;
    private final int sizeMb;
    private final List<String> tools; // e.g. maven, jdk, shell

    public BaseImage(String name, int sizeMb, List<String> tools) {
        this.name = name;
        this.sizeMb = sizeMb;
        this.tools = List.copyOf(tools);
    }
    public String getName()        { return name; }
    public int getSizeMb()         { return sizeMb; }
    public List<String> getTools() { return tools; }
}
