package com.bank.multistage;

import java.util.logging.Logger;

// Stage 1: heavy toolchain base compiles source into an artifact.
public class BuildStage {
    private static final Logger log = Logger.getLogger(BuildStage.class.getName());
    private final BaseImage toolchain;

    public BuildStage(BaseImage toolchain) { this.toolchain = toolchain; }

    public Artifact build() {
        log.info(() -> "BUILD stage on " + toolchain.getName() + " (" + toolchain.getSizeMb()
                + "MB, tools=" + toolchain.getTools() + ")");
        log.info("  mvn clean package -> transfer-service.jar");
        return new Artifact("transfer-service.jar", 45); // the JAR is small
    }
    public BaseImage getToolchain() { return toolchain; }
}
