package com.bank.multistage;

import java.util.logging.Logger;

// Stage 2: slim runtime base + ONLY the artifact (COPY --from=build).
public class RuntimeStage {
    private static final Logger log = Logger.getLogger(RuntimeStage.class.getName());
    private final BaseImage runtimeBase;

    public RuntimeStage(BaseImage runtimeBase) { this.runtimeBase = runtimeBase; }

    // Final image size = slim base + artifact ONLY (toolchain discarded).
    public int assembleFinalImage(Artifact artifact) {
        int finalSize = runtimeBase.getSizeMb() + artifact.getSizeMb();
        log.info(() -> "RUNTIME stage on " + runtimeBase.getName() + " (" + runtimeBase.getSizeMb()
                + "MB), COPY --from=build " + artifact.getName());
        log.info(() -> "Final image contains tools=" + runtimeBase.getTools()
                + " (NO build toolchain)");
        log.info(() -> "Final image size = " + finalSize + "MB");
        return finalSize;
    }
}
