package com.bank.multistage;

import java.util.List;
import java.util.logging.*;

public class MultiStageDemo {
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new MultiStageLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Logger log = Logger.getLogger(MultiStageDemo.class.getName());

        BaseImage toolchain  = new BaseImage("maven:3.9-eclipse-temurin-21", 680,
                List.of("maven", "jdk-compiler", "shell", "pkg-manager"));
        BaseImage slimRuntime = new BaseImage("eclipse-temurin:21-jre", 230,
                List.of("jre"));

        log.info("=== SINGLE-STAGE (everything shipped) ===");
        BuildStage build = new BuildStage(toolchain);
        Artifact jar = build.build();
        int singleStageSize = toolchain.getSizeMb() + jar.getSizeMb(); // toolchain stays!
        log.info("Single-stage final image = " + singleStageSize + "MB (toolchain included)");

        log.info("=== MULTI-STAGE (only artifact copied to slim runtime) ===");
        RuntimeStage runtime = new RuntimeStage(slimRuntime);
        int multiStageSize = runtime.assembleFinalImage(jar);

        log.info("=== RESULT ===");
        log.info("Saved " + (singleStageSize - multiStageSize) + "MB by dropping the toolchain");
    }
}

// ─── Would be in MultiStageLogFormatter.java in a real project ───
class MultiStageLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
