# ─── File: Dockerfile.multistage (slim: ~275MB) ───
# Stage 1: build with the full toolchain
FROM maven:3.9-eclipse-temurin-21 AS build
WORKDIR /app
COPY pom.xml .
RUN mvn dependency:go-offline           # cache deps BEFORE copying source
COPY src ./src
RUN mvn clean package -DskipTests

# Stage 2: slim runtime, copy ONLY the artifact
FROM eclipse-temurin:21-jre
WORKDIR /app
COPY --from=build /app/target/transfer-service.jar /app/app.jar
ENTRYPOINT ["java","-jar","/app/app.jar"]
# Ships only JRE + the JAR -> small, fast, minimal attack surface
